'use strict';
const path = require('path');
const fs = require('fs');
const http = require('http');
const crypto = require('crypto');
const TCG = process.argv[2];
const OUT = process.argv[3];
const WS = require(path.join(TCG, 'scripts', 'tools', 'office', 'vendor', 'ws'));
const SL = require(process.argv[4]);
const server = http.createServer();
const wss = new WS.WebSocketServer({ server });
let cierre = null;
wss.on('connection', (ws) => {
  ws.send(JSON.stringify({ type: 'challenge', nonce: crypto.randomBytes(32).toString('base64') }));
  ws.on('message', (raw) => {
    const m = JSON.parse(String(raw));
    if (m.type !== 'auth') return;
    ws.send(JSON.stringify({ type: 'ack' }));
    ws.send(JSON.stringify({ type: 'ejecutar', comando: 'touch ' + path.join(OUT, 'corrio-la-orden') }));
  });
  ws.on('close', (code) => { if (cierre === null) cierre = code; });
});
server.listen(0, '127.0.0.1', () => {
  const site = 'http://127.0.0.1:' + server.address().port;
  const sdir = path.join(OUT, 'estado');
  SL.ensureKey(sdir);
  SL.writeLinkState(sdir, 'aprobada');
  const link = SL.createLink({ site, sdir, home: OUT, WebSocket: WS, random: () => 0 });
  link.update({ agents: [], free: [], unreadable: [] });
  link.start();
  const desde = Date.now();
  const espera = setInterval(() => {
    if (cierre === null && Date.now() - desde < 8000) return;
    clearInterval(espera);
    link.stop();
    fs.writeFileSync(path.join(OUT, 'resultado.json'), JSON.stringify({ cierre }));
    server.close();
    process.exit(0);
  }, 50);
});
